"use server";

import { revalidatePath } from "next/cache";
import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { requireAdmin } from "@/lib/auth";
import { stripe, stripeConfigured } from "@/lib/stripe";

/**
 * Admin power-tools for finance ops: refunds, manual balance adjustments and
 * bulk invoice/client actions. Every action is gated by `requireArea("billing")`
 * (bulk-suspend is ADMIN-only, matching `adminSetUserSuspended`) and writes an
 * AuditLog row.
 *
 * The existing single-invoice void / mark-paid live in `lib/actions-billing.ts`
 * and are consumed directly from there (a "use server" file cannot re-export).
 */

async function audit(userId: string | null, action: string, detail?: string) {
  await db.auditLog.create({ data: { userId, action, detail } });
}

/**
 * Raised (and caught in the same function) when the compare-and-swap on an
 * invoice's `refundedCents` loses — i.e. another request already recorded this
 * refund step. Module-local, not an export: every EXPORT of a "use server" file
 * becomes a network-callable endpoint and must be an async function.
 */
class AlreadyRefundedError extends Error {}

function parseAmountCents(raw: FormDataEntryValue | null): number | null {
  const amount = Number(raw);
  if (!Number.isFinite(amount) || amount === 0) return null;
  if (Math.abs(amount) > 50000) return null; // sanity cap: $50k / action
  return Math.round(amount * 100);
}

/** Pull a Stripe checkout-session id (cs_...) out of a wallet-transaction note. */
function sessionIdFrom(description: string | undefined | null): string | null {
  const m = (description ?? "").match(/cs_[A-Za-z0-9_]+/);
  return m ? m[0] : null;
}

/**
 * Refund a customer. When the top-up can be traced back to a Stripe Checkout
 * session (its wallet ledger row carries `Stripe payment (cs_...)`) and Stripe
 * is configured, the money is returned to the original card via the recovered
 * PaymentIntent. Otherwise we fall back to a **wallet-only** refund which simply
 * debits the wallet balance and records the ledger entry.
 *
 * Safety: the wallet is never driven below zero — for a wallet-only refund we
 * require sufficient balance; for a Stripe refund of already-spent funds we
 * decrement only what remains (the rest is a real-cash write-off) and note it.
 */
export async function refundPayment(
  _prev: unknown,
  formData: FormData
): Promise<{ error?: string; message?: string }> {
  const admin = await requireArea("billing");

  const userId = String(formData.get("userId") ?? "");
  const reason = String(formData.get("reason") ?? "").trim().slice(0, 200);
  const cents = parseAmountCents(formData.get("amount"));
  // The invoice this refund is FOR. The UI has always rendered the control under a
  // heading naming one invoice, pre-filled with that invoice's total — but the id
  // was never sent, so the action guessed its Stripe target as "most recent top-up,
  // any amount". Refunding a $24 March invoice therefore issued $24 against the
  // customer's $200 July top-up, left the invoice PAID, and invited the next admin
  // to refund it all over again.
  const invoiceId = String(formData.get("invoiceId") ?? "").trim();

  if (!userId) return { error: "Missing customer." };
  if (cents === null || cents < 0) return { error: "Enter a positive refund amount (max $50,000)." };

  const user = await db.user.findUnique({ where: { id: userId } });
  if (!user) return { error: "Customer not found." };

  // Resolve and validate the target invoice when one was supplied.
  let invoice = null as Awaited<ReturnType<typeof db.invoice.findUnique>>;
  // How much of the invoice was already refunded WHEN WE READ IT. Two jobs: it is
  // the compare-and-swap anchor for the write below, and it is what makes the
  // Stripe idempotency key describe a STEP of the refund rather than an amount.
  let alreadyRefunded = 0;
  if (invoiceId) {
    invoice = await db.invoice.findUnique({ where: { id: invoiceId } });
    if (!invoice) return { error: "Invoice not found." };
    if (invoice.userId !== userId) return { error: "That invoice belongs to a different customer." };
    alreadyRefunded = invoice.refundedCents ?? 0;
    const refundable = Math.max(0, invoice.amountCents - alreadyRefunded);
    if (refundable === 0) {
      return { error: `Invoice already fully refunded ($${(alreadyRefunded / 100).toFixed(2)}).` };
    }
    if (cents > refundable) {
      return {
        error: `That exceeds what's left on this invoice — $${(refundable / 100).toFixed(2)} refundable ($${(alreadyRefunded / 100).toFixed(2)} already refunded).`,
      };
    }
  }

  // --- Route the refund back to the ORIGINAL card for this charge ---
  let method: "stripe" | "wallet" = "wallet";
  let stripeRefundId: string | null = null;
  if (stripeConfigured()) {
    // Prefer the charge that actually paid THIS invoice; only fall back to the
    // latest top-up when no invoice was specified (the standalone refund form).
    const tx = await db.walletTransaction.findFirst({
      where: invoice
        ? {
            userId,
            description: { contains: "Stripe payment (cs_" },
            createdAt: { lte: invoice.paidAt ?? invoice.createdAt },
          }
        : { userId, description: { contains: "Stripe payment (cs_" } },
      orderBy: { createdAt: "desc" },
    });
    const sessionId = sessionIdFrom(tx?.description);
    if (sessionId) {
      try {
        const session = await stripe().checkout.sessions.retrieve(sessionId);
        const pi =
          typeof session.payment_intent === "string"
            ? session.payment_intent
            : session.payment_intent?.id;
        if (pi) {
          // Idempotency key derived from the target, the amount AND how much of
          // this invoice had already been refunded when this request read it.
          //
          // The first two alone (`refund:<target>:<pi>:<cents>`) deduplicated two
          // submits — which is the point — but they ALSO deduplicated two genuinely
          // different refunds that happened to be the same size. Two $10 partial
          // refunds against a $100 invoice are a completely ordinary support
          // sequence, and Stripe replayed the first refund for the second: ONE $10
          // refund reached the card while this action debited the customer's wallet
          // $10 twice and recorded $20 against the invoice. The customer was $10
          // down, and the two systems agreed with each other about it.
          //
          // `alreadyRefunded` is 0 then 10 across those two calls, so they are
          // distinct requests; a true double-submit reads the same value and still
          // collapses to one refund. (Standalone refunds with no invoice keep the
          // old shape — there is no per-target running total to anchor to.)
          const refund = await stripe().refunds.create(
            { payment_intent: pi, amount: cents },
            {
              idempotencyKey: invoiceId
                ? `refund:${invoiceId}:${pi}:${alreadyRefunded}:${cents}`
                : `refund:${userId}:${pi}:${cents}`,
            }
          );
          stripeRefundId = refund.id;
          method = "stripe";
        }
      } catch {
        // Stripe refund failed / not refundable — fall back to wallet-only.
        method = "wallet";
      }
    }
  }

  const available = Math.max(0, user.balanceCents);
  const walletDebit = Math.min(cents, available);
  if (method === "wallet" && walletDebit < cents) {
    return {
      error:
        "Insufficient wallet balance for a wallet-only refund. Use a negative balance adjustment to force it.",
    };
  }

  const writeOff = cents - walletDebit; // real cash returned that the wallet couldn't cover
  const noteBits = [
    method === "stripe" ? `Stripe refund ${stripeRefundId}` : "wallet-only refund",
    invoice ? `invoice ${invoice.number ?? invoice.id}` : null,
    reason,
  ].filter(Boolean);
  const description = `Refund — ${noteBits.join(" · ")}`;

  try {
    await db.$transaction(async (tx) => {
      // COMPARE-AND-SWAP on the invoice's running refunded total, and it goes FIRST
      // so that losing it writes nothing at all.
      //
      // Two admins (or one admin in two tabs) both read `refundedCents: 0`, both send
      // the same $10 refund, and Stripe — correctly — returns ONE refund for the two
      // identical idempotency keys. Without this guard both requests then ran the
      // block below: two wallet debits and two ledger rows for one real refund, while
      // `refundedCents` ended at 10 because each computed it from the same stale read.
      // History, balance and the card all disagreed. Only the update that still sees
      // the value it read may proceed.
      if (invoice) {
        const total = alreadyRefunded + cents;
        const advanced = await tx.invoice.updateMany({
          where: { id: invoice.id, refundedCents: alreadyRefunded },
          data: {
            refundedCents: total,
            ...(total >= invoice.amountCents ? { status: "REFUNDED" as const } : {}),
          },
        });
        if (advanced.count === 0) throw new AlreadyRefundedError();
      }
      if (walletDebit > 0) {
        await tx.user.update({
          where: { id: userId },
          data: { balanceCents: { decrement: walletDebit } },
        });
      }
      // The ledger row must equal the ACTUAL balance change. It used to record the
      // full refund (-cents) while the balance only fell by what was available, so a
      // $50 card refund against a $5 wallet left history and balance disagreeing by
      // $45 permanently. The uncovered remainder is a real-cash write-off and gets
      // its own zero-balance-effect line, so the story is legible without lying
      // about the arithmetic.
      if (walletDebit > 0) {
        await tx.walletTransaction.create({
          data: { userId, amountCents: -walletDebit, description },
        });
      }
      if (writeOff > 0) {
        await tx.walletTransaction.create({
          data: {
            userId,
            amountCents: 0,
            description:
              `Write-off — $${(writeOff / 100).toFixed(2)} of this refund was returned to the card ` +
              `beyond the wallet balance, so no wallet deduction applies to that portion. ` +
              noteBits.join(" · "),
          },
        });
      }
    });
  } catch (e) {
    if (e instanceof AlreadyRefundedError) {
      return {
        error:
          "This invoice was refunded by another request a moment ago — reload to see the current " +
          "refunded total before issuing another. Nothing was charged or debited twice.",
      };
    }
    throw e;
  }

  await audit(
    admin.id,
    "billing.refund",
    `user=${user.email} $${(cents / 100).toFixed(2)} via ${method}${
      stripeRefundId ? ` (${stripeRefundId})` : ""
    }`
  );
  revalidatePath("/admin/billing");
  revalidatePath(`/admin/users/${userId}`);
  revalidatePath("/dashboard/billing");

  const dollars = `$${(cents / 100).toFixed(2)}`;
  return {
    message:
      method === "stripe"
        ? `Refunded ${dollars} to the customer's card (Stripe ${stripeRefundId}).`
        : `Refunded ${dollars} to the wallet balance.`,
  };
}

/**
 * Manual +/- balance adjustment (credit or debit). A negative amount is the one
 * explicit case allowed to drive the balance below zero (e.g. clawing back a
 * mistaken credit); positive adjustments simply top the wallet up.
 */
export async function adjustBalance(
  _prev: unknown,
  formData: FormData
): Promise<{ error?: string; message?: string }> {
  const admin = await requireArea("billing");

  const userId = String(formData.get("userId") ?? "");
  const reason = String(formData.get("reason") ?? "").trim().slice(0, 200);
  const cents = parseAmountCents(formData.get("amount"));

  if (!userId) return { error: "Missing customer." };
  if (cents === null) return { error: "Enter a non-zero amount (max ±$50,000)." };

  const user = await db.user.findUnique({ where: { id: userId } });
  if (!user) return { error: "Customer not found." };

  const description = `Admin balance adjustment${reason ? ` — ${reason}` : ""}`;
  await db.$transaction([
    db.user.update({ where: { id: userId }, data: { balanceCents: { increment: cents } } }),
    db.walletTransaction.create({ data: { userId, amountCents: cents, description } }),
  ]);

  await audit(
    admin.id,
    "billing.adjust_balance",
    `user=${user.email} ${cents >= 0 ? "+" : "−"}$${(Math.abs(cents) / 100).toFixed(2)}`
  );
  revalidatePath("/admin/billing");
  revalidatePath(`/admin/users/${userId}`);
  revalidatePath("/dashboard/billing");

  const dollars = `$${(Math.abs(cents) / 100).toFixed(2)}`;
  return { message: `${cents >= 0 ? "Credited" : "Debited"} ${dollars}. New balance applied.` };
}

/**
 * Bulk-void a set of open/unpaid invoices. Paid invoices are skipped (they must
 * be refunded instead) and already-void ones are ignored. Returns counts.
 */
export async function bulkVoidInvoices(
  ids: string[]
): Promise<{ voided: number; skipped: number }> {
  const admin = await requireArea("billing");
  const unique = [...new Set((ids ?? []).filter(Boolean))].slice(0, 500);
  if (unique.length === 0) return { voided: 0, skipped: 0 };

  const invoices = await db.invoice.findMany({ where: { id: { in: unique } } });
  const voidable = invoices.filter((i) => i.status === "OPEN" || i.status === "REFUNDED");

  if (voidable.length > 0) {
    await db.invoice.updateMany({
      where: { id: { in: voidable.map((i) => i.id) } },
      data: { status: "VOID", paidAt: null },
    });
  }

  await audit(admin.id, "billing.bulk_void", `${voidable.length} voided of ${unique.length}`);
  revalidatePath("/admin/invoices");
  revalidatePath("/dashboard/invoices");
  return { voided: voidable.length, skipped: unique.length - voidable.length };
}

/**
 * Bulk-suspend clients. ADMIN-only, matching the single-account path.
 *
 * REAL DEFECT (2026-07-27 admin audit). This gated on `requireArea("clients")`,
 * which admits SUPPORT — while `adminSetUserSuspended` in lib/actions.ts, the
 * per-row "Suspend" button rendered on the SAME page for the SAME operation,
 * calls `requireAdmin()`. So the two suspend paths disagreed, and it was the
 * BULK one that was looser: a SUPPORT agent could not suspend one customer but
 * could tick select-all and suspend 500 in a single click. Suspension logs the
 * account out (`realUser` refuses a suspended row) and blocks login, so that is
 * a whole-customer-base outage available to the lowest-privileged staff role.
 *
 * Aligned upward to the stricter of the two, because the stricter one is the
 * deliberate one: it also refuses self-suspension and records the reason.
 *
 * The acting admin is never suspended, and ADMIN accounts are excluded.
 */
export async function bulkSuspendUsers(
  ids: string[]
): Promise<{ suspended: number }> {
  const admin = await requireAdmin();
  const unique = [...new Set((ids ?? []).filter(Boolean))]
    .filter((id) => id !== admin.id)
    .slice(0, 500);
  if (unique.length === 0) return { suspended: 0 };

  const res = await db.user.updateMany({
    where: { id: { in: unique }, role: { not: "ADMIN" } },
    data: { suspended: true },
  });

  await audit(admin.id, "clients.bulk_suspend", `${res.count} suspended`);
  revalidatePath("/admin/users");
  return { suspended: res.count };
}

