export const dynamic = "force-dynamic";

function dayKey(d: Date): string {
  return d.toISOString().slice(0, 10);
}

export default async function AdminOverview() {
  await requireArea("overview");

  const since24h = new Date(Date.now() - 24 * 3600_000);
  const since14d = new Date(Date.now() - 14 * 86400_000);

  const [
    activeServers,
    serverOwners,
    runningCount,
    totalServers,
    openTickets,
    failedJobs24h,
    liabilities,
    revenueTx,
    activeJobs,
    recentAudit,
  ] = await Promise.all([
    db.server.findMany({
      where: { isFree: false, status: { notIn: ["DELETING"] } },
      select: {
        status: true,
        isFree: true,
        termMonths: true,
        plan: { select: { priceCents: true } },
        // A game server is sold at the game plan's flat price, not the base VPS
        // plan's — see `serverMonthlyCents` and the incident in `renewNow`.
        gamePlan: { select: { priceCents: true, termMonths: true } },
      },
    }),
    // Owners of a server that still EXISTS as far as the platform is concerned.
    // Unfiltered, this counted a customer whose only server is mid-teardown as an
    // "active customer" while the Servers card next to it had already excluded
    // that same machine.
    db.server.groupBy({ by: ["userId"], where: { status: { notIn: ["DELETING"] } } }),
    db.server.count({ where: { status: "RUNNING" } }),
    db.server.count({ where: { status: { notIn: ["DELETING"] } } }),
    db.ticket.count({ where: { status: { in: ["OPEN", "CUSTOMER_REPLY"] } } }),
    db.job.count({ where: { status: "FAILED", updatedAt: { gte: since24h } } }),
    db.user.aggregate({ _sum: { balanceCents: true } }),
    // Revenue, not "any wallet debit": refunds and affiliate payouts are also
    // negative rows and used to push this chart UP. See REVENUE_WHERE.
    db.walletTransaction.findMany({
      where: { ...REVENUE_WHERE, createdAt: { gte: since14d } },
      select: { amountCents: true, createdAt: true },
