import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { stripComments, stripCommentsAndStrings } from "./_source-tools.ts";

/**
 * Friction and honesty on the admin controls that spend money or destroy data.
 *
 * Two failures this guards:
 *  1. A confirmation that understates the consequence. A full server delete runs
 *     `qm destroy --purge`, which frees EVERY disk the vmid owns — including any
 *     attached block-storage volume the customer is billed for separately — and
 *     the worker then deletes those Volume rows (worker/index.ts `remove`). The
 *     confirmation enumerated "VM, disk, IP and port forwards" and omitted the
 *     volumes, so an operator could destroy separately-billed customer data it
 *     never warned them about. The reinstall path already refuses when volumes
 *     exist; delete takes them, so the warning has to say so.
 *  2. A money mover with no confirmation. Refund (to a live card) and a negative
 *     balance adjustment (below zero) fired on a single click while every
 *     neighbouring destructive control confirmed.
 *
 * `stripComments` keeps string literals (these assertions read the confirmation
 * COPY); `stripCommentsAndStrings` is used where the assertion is about code SHAPE
 * (an onSubmit guard exists) so a mention of `window.confirm` inside a comment or
 * a string can't satisfy it. See test/_source-tools.ts.
 */

const ROOT = join(import.meta.dirname, "..");
const withStrings = (rel: string) => stripComments(readFileSync(join(ROOT, rel), "utf8"));
const shapeOnly = (rel: string) => stripCommentsAndStrings(readFileSync(join(ROOT, rel), "utf8"));

/* ------------------------------------------------------------------ *
 * 1. Delete names the data volumes it destroys
 * ------------------------------------------------------------------ */

test("the delete confirmation warns that attached data volumes are destroyed", () => {
  // The confirm() copy in the admin delete button.
  const src = withStrings("components/admin/ServerAdminActions.tsx");
  assert.match(
    src,
    /Really destroy[\s\S]*?volume/i,
    "the destroy confirmation must state that attached data volumes are removed too — " +
      "a full delete purges every disk the VM owns",
  );
});

test("the server danger-zone copy names the volumes a delete purges", () => {
  const src = withStrings("app/admin/servers/[id]/page.tsx");
  assert.match(
    src,
    /Destroys the VM[\s\S]*?volume/i,
    "the danger-zone description must include attached block-storage volumes",
  );
});

/* ------------------------------------------------------------------ *
 * 2. Money movers confirm before firing
 * ------------------------------------------------------------------ */

test("both admin money forms confirm before moving a customer's money", () => {
  // RefundForm (refund to card / wallet) and AdjustBalanceForm (credit/debit,
  // allowed below zero) must each guard submission with a confirm that can cancel.
  const src = shapeOnly("components/admin/RefundControls.tsx");
  const confirms = (src.match(/window\.confirm\(/g) ?? []).length;
  assert.ok(
    confirms >= 2,
    `expected both the refund and the balance-adjust form to confirm before submitting; ` +
      `found ${confirms} window.confirm call(s)`,
  );
  assert.ok(
    src.includes("preventDefault("),
    "a confirm that cannot cancel the submit is decorative — the onSubmit guard must preventDefault on cancel",
  );
});

